 const response=new Response(new ReadableStream({start(controller){void gate.promise.then(value=>{if(!canceled){controller.enqueue(new Uint8Array(value));controller.close();}},error=>{if(!canceled)controller.error(error);});},cancel(){canceled=true;}}),{headers:{'content-length':'2','content-type':'application/json'}});
