test('a genuine underlying stream cancellation rejection keeps the failed owner and blocks release',async()=>{
 const baseline=retainedAllocations(),f=fixture(Current);await f.initial();const {completion}=await f.hold(),outcome=completion.then(()=>null,error=>error),failure=Error('Underlying cancellation failed');let cancellations=0;
 const response=new Response(new ReadableStream({cancel(){cancellations++;throw failure;}}),{headers:{'content-length':'2','content-type':'application/json'}});f.pending.shift().resolve(response);await flush();
 const release=f.instance.releaseDocument().then(()=>null,error=>error),error=expectedCleanup(await outcome);assert(error.errors.includes(failure));assert.equal(cancellations,1);assert.equal(error.resource.response,response);assert.equal(response.body.locked,false);
 const releaseError=await release;assert(releaseError instanceof AggregateError);assert(releaseError.errors.includes(error));assert.equal(f.instance.lifecycle.cleanupFailures,1);assert.equal(f.instance.lifecycle.models,0);assert.equal(f.instance.lifecycle.pendingOperations,0);assert.equal(f.instance.lifecycle.pendingPins,0);
 assert.deepEqual(retainedAllocations(),{records:baseline.records+1,cpu:baseline.cpu+2,prompt:baseline.prompt+2,handles:baseline.handles+2,unused:baseline.unused+2});await assert.rejects(error.retry(),value=>value===error);assert.equal(cancellations,1);assert.equal(f.saved.length,0);
});

